-- Law names — Built-in statute list, generated by tool/generate_supabase_seed.dart.
-- Do not edit by hand: change lib/core/constants/pre_seeded_data.dart and re-run
--   dart run tool/generate_supabase_seed.dart
--
-- The 57 names of docs/seed_data_test/LawsOfBangladesh.md, under its seven
-- categories. Every ID is the same stable tag the Drift `seed_v3` migration uses,
-- so the phone, the server and a backup name the same row. Rows are upserted with
-- `on conflict (id) do update ... where is_user_modified = false`, mirroring the
-- client: a name the user or firm renamed is never overwritten by a later seed.
--
-- Table class: push/pull domain (editable, firm-shared reference data).

on conflict (id) do update set
  name = excluded.name,
  category = excluded.category,
  order_index = excluded.order_index,
  updated_at = excluded.updated_at
where laws.is_user_modified = false;

